export function shuffle(items,random=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function grade(questions,ids,responses){const map=new Map(questions.map(q=>[q.id,q]));let correct=0,answered=0;const topics={};const missed=[];for(const id of ids){const q=map.get(id);if(!q)continue;topics[q.topic]??={total:0,correct:0,answered:0};topics[q.topic].total++;const selected=responses[id];const valid=Number.isInteger(selected)&&selected>=0&&selected<q.options.length;if(valid){answered++;topics[q.topic].answered++;}if(valid&&selected===q.answer){correct++;topics[q.topic].correct++;}else missed.push(id);}return{total:ids.length,answered,correct,unanswered:ids.length-answered,percent:ids.length?Math.round(correct/ids.length*100):0,topics,missed};}
export function newAttempt(questions,{scope='all',size='all',randomize=true,ids=null}={}){let pool=ids?questions.filter(q=>ids.includes(q.id)):questions.filter(q=>scope==='all'||scope==='slides'&&q.source.kind==='slides'||scope==='conference'&&q.source.kind==='documents'||q.topic===scope);if(randomize)pool=shuffle(pool);if(size!=='all')pool=pool.slice(0,Number(size));return{version:1,ids:pool.map(q=>q.id),orders:Object.fromEntries(pool.map(q=>[q.id,shuffle(q.options.map((_,i)=>i))])),current:0,responses:{},drafts:{},finished:false,scope};}
export function validAttempt(a,questions){if(!a||a.version!==1||!Array.isArray(a.ids)||!a.ids.length||new Set(a.ids).size!==a.ids.length||!a.responses||!a.orders||!a.drafts||!Number.isInteger(a.current)||a.current<0||a.current>=a.ids.length)return false;const map=new Map(questions.map(q=>[q.id,q]));return a.ids.every(id=>{const q=map.get(id),order=a.orders[id];return q&&Array.isArray(order)&&order.length===q.options.length&&new Set(order).size===order.length&&order.every(i=>Number.isInteger(i)&&i>=0&&i<q.options.length)&&(a.responses[id]===undefined||Number.isInteger(a.responses[id])&&a.responses[id]>=0&&a.responses[id]<q.options.length);});}
